# Unit 3: Development and Learning. Original items. Q(test, difficulty, skill, stem, [key, wrong, wrong, wrong], explanation)

ITEMS = [
    # ---------------- Practice Test 1 ----------------
    Q(1, 1, "Themes and methods in development",
      "A researcher tests the same group of children every two years from age 4 to age 20. This is a",
      ["longitudinal study", "cross-sectional study", "case study", "naturalistic observation"],
      "A longitudinal study follows the same people over time. A cross-sectional study compares different age groups at one point in time."),
    Q(1, 1, "Physical development",
      "Heavy drinking during pregnancy can cause facial abnormalities and intellectual disability in the child. In this case alcohol acts as",
      ["a teratogen", "an agonist", "a hormone", "a neurotransmitter"],
      "A teratogen is any agent, such as alcohol or some drugs and viruses, that can harm a developing embryo or fetus. Fetal alcohol syndrome is the pattern described."),
    Q(1, 1, "Cognitive development",
      "A 10-month-old searches under a blanket for a toy she just watched being hidden there. She has developed",
      ["object permanence", "conservation", "egocentrism", "a theory of mind"],
      "Object permanence, the understanding that things continue to exist when out of sight, develops during Piaget's sensorimotor stage. Conservation comes much later, in the concrete operational stage."),
    Q(1, 2, "Cognitive development",
      "Two rows of seven buttons are lined up one-to-one, and a 4-year-old agrees they are the same. After one row is spread out, he says the longer row has more buttons. He lacks",
      ["conservation", "object permanence", "accommodation", "stranger anxiety"],
      "Conservation is understanding that a quantity, here the number of buttons, stays the same when its arrangement changes. Preoperational children focus on one dimension, such as the length of the row, and miss it."),
    Q(1, 2, "Cognitive development",
      "A parent helps a child with a puzzle she cannot yet finish alone, then steps back gradually as she improves. In Vygotsky's terms, this is",
      ["scaffolding", "assimilation", "imprinting", "shaping"],
      "Scaffolding is temporary support within the zone of proximal development, withdrawn as the learner becomes able to do the task alone. Assimilation is Piaget's term for fitting new experiences into existing schemas."),
    Q(1, 2, "Language development",
      "A 3-year-old says \"I goed to the park\" and \"I saw two mouses.\" These errors show",
      ["overgeneralization", "telegraphic speech", "babbling", "a critical period"],
      "Overgeneralization is applying a grammar rule, such as adding -ed or -s, to words that are exceptions. It shows the child has learned the rule. Telegraphic speech is the two-word stage, such as \"want milk.\""),
    Q(1, 1, "Social-emotional development",
      "In the strange situation, a toddler is upset when his mother leaves and is quickly comforted when she returns. He shows",
      ["secure attachment", "avoidant attachment", "anxious attachment", "disorganized attachment"],
      "Securely attached children use the caregiver as a safe base: distress at separation and easy comfort at reunion. An anxiously attached child stays upset and may resist comfort when the caregiver returns."),
    Q(1, 1, "Social-emotional development",
      "Parents who set clear rules, explain their reasons and listen to their teenager's views have which parenting style?",
      ["Authoritative", "Authoritarian", "Permissive", "Uninvolved"],
      "Authoritative parents combine high demands with warmth and discussion. Authoritarian parents set strict rules and expect obedience without explanation."),
    Q(1, 1, "Classical conditioning",
      "A dog drools at the sound of a can opener that has often come just before its dinner. The sound of the can opener is",
      ["a conditioned stimulus", "an unconditioned stimulus", "a conditioned response", "an unconditioned response"],
      "The sound was neutral until it was paired with food, so it is now a conditioned stimulus. The food itself is the unconditioned stimulus, and the drooling to the sound is the conditioned response."),
    Q(1, 2, "Operant conditioning",
      "Mark buckles his seat belt to stop the car's beeping, and he now buckles up sooner each time. This is",
      ["negative reinforcement", "positive reinforcement", "negative punishment", "positive punishment"],
      "Removing an unpleasant stimulus (the beeping) strengthens the behavior, so this is negative reinforcement. Punishment would weaken the behavior, not strengthen it."),
    Q(1, 1, "Social and cognitive factors in learning",
      "After watching an adult hit an inflatable doll, children in Bandura's study were more likely to hit the doll themselves. This shows",
      ["observational learning", "latent learning", "insight learning", "classical conditioning"],
      "Observational learning, or modeling, is learning by watching others. Latent learning is learning that is not shown until there is a reason to show it."),

    # ---------------- Practice Test 2 ----------------
    Q(2, 2, "Themes and methods in development",
      "To study memory and age, a researcher tests groups of 20-, 40- and 60-year-olds in the same month. A weakness of this design is",
      ["differences between generations", "participants dropping out", "practice effects from retesting", "the years needed to finish"],
      "A cross-sectional study compares people born in different eras, so cohort differences such as schooling can be mistaken for age effects. Dropout and practice effects are problems of longitudinal studies."),
    Q(2, 1, "Physical development",
      "The first menstrual period, a milestone of puberty, is called",
      ["menarche", "spermarche", "menopause", "maturation"],
      "Menarche is the first menstrual period. Spermarche is the first ejaculation, and menopause is the end of menstruation in midlife."),
    Q(2, 1, "Cognitive development",
      "A 3-year-old covers her own eyes and believes that others can no longer see her. Piaget would say she shows",
      ["egocentrism", "object permanence", "conservation", "abstract reasoning"],
      "Egocentrism, in Piaget's preoperational stage, is difficulty taking another person's point of view. The child assumes others see what she sees."),
    Q(2, 2, "Cognitive development",
      "A 15-year-old can reason about hypothetical situations and test ideas systematically. Piaget would place her in which stage?",
      ["Formal operational", "Concrete operational", "Preoperational", "Sensorimotor"],
      "The formal operational stage, from about age 12, adds abstract and hypothetical reasoning. Concrete operational thinkers reason logically about concrete events only."),
    Q(2, 2, "Cognitive development",
      "A toddler who called every man she met \"Daddy\" learns that only her father is Daddy and that other men are a different category. Piaget would call this change",
      ["accommodation", "assimilation", "conservation", "habituation"],
      "Accommodation is changing a schema, or making a new one, to fit new information. Calling every man \"Daddy\" in the first place, fitting new people into the existing schema, would be assimilation."),
    Q(2, 3, "Cognitive development",
      "A child understands that her friend will look for a toy where the friend last saw it, not where it was moved while the friend was out of the room. The child has",
      ["a theory of mind", "object permanence", "a gender schema", "conservation"],
      "A theory of mind is understanding that others have their own beliefs, which can be false. Object permanence concerns whether objects exist out of sight, not what other people believe."),
    Q(2, 1, "Social-emotional development",
      "Harlow's infant monkeys clung to a soft cloth mother rather than to a wire mother that gave milk. This showed the importance of",
      ["contact comfort", "food rewards", "imprinting", "stranger anxiety"],
      "The monkeys sought the cloth mother for comfort, especially when frightened, showing that attachment rests on contact comfort more than on feeding."),
    Q(2, 1, "Social-emotional development",
      "According to Erikson, the main challenge of adolescence is",
      ["identity versus role confusion", "trust versus mistrust", "generativity versus stagnation", "industry versus inferiority"],
      "Erikson saw adolescence as the time for forming a sense of self. Intimacy versus isolation follows in young adulthood, and industry versus inferiority comes in the school years."),
    Q(2, 2, "Classical conditioning",
      "After a conditioned response has been extinguished, it reappears in weaker form following a rest period. This is",
      ["spontaneous recovery", "stimulus generalization", "acquisition", "higher-order conditioning"],
      "Spontaneous recovery is the return of an extinguished conditioned response after a pause. It shows extinction suppresses the response rather than erasing it."),
    Q(2, 1, "Operant conditioning",
      "Slot machines pay out after an unpredictable number of plays. This schedule of reinforcement is",
      ["variable-ratio", "fixed-ratio", "variable-interval", "fixed-interval"],
      "Reinforcement after an unpredictable number of responses is variable-ratio. It produces high, steady responding that is hard to extinguish."),
    Q(2, 2, "Social and cognitive factors in learning",
      "Rats that explored a maze without any reward ran it quickly once food was placed at the end. Tolman said they had formed a cognitive map, an example of",
      ["latent learning", "observational learning", "shaping", "classical conditioning"],
      "Latent learning happens without reinforcement and shows up only when there is a reason to use it. Shaping requires reinforcing closer and closer approximations."),

    # ---------------- Drill only ----------------
    Q(0, 2, "Gender and sexual orientation",
      "A boy sorts toys into toys for boys and toys for girls and plays only with the ones he thinks fit his own group. He is using",
      ["a gender schema", "object permanence", "a sensitive period", "egocentrism"],
      "A gender schema is a mental framework for what is typical of each gender, which children use to organize experience and guide their behavior."),
    Q(0, 1, "Physical development",
      "A newborn turns her head toward a touch on the cheek and opens her mouth. This is",
      ["the rooting reflex", "the Moro reflex", "the grasping reflex", "the Babinski reflex"],
      "The rooting reflex helps a newborn find the nipple. The Moro reflex is the startle response: arms flung out, then pulled in."),
    Q(0, 1, "Social-emotional development",
      "Lorenz's goslings followed him because he was the first moving object they saw soon after hatching. This is",
      ["imprinting", "contact comfort", "habituation", "shaping"],
      "Imprinting is rapid attachment formed during a critical period early in life. Contact comfort is Harlow's finding about monkeys and soft mothers."),
    Q(0, 1, "Operant conditioning",
      "A trainer teaches a dog to roll over by rewarding it first for lying down, then for rolling onto its side, then for a full roll. This is",
      ["shaping", "generalization", "extinction", "modeling"],
      "Shaping reinforces successive approximations of the target behavior. Modeling would mean the dog learns by watching another dog."),
    Q(0, 2, "Classical conditioning",
      "After getting sick hours after eating shrimp, Ana avoids shrimp for years. This learning is unusual because it formed from",
      ["one pairing with a long delay", "many pairings over several weeks", "a reward that followed eating", "watching someone else get sick"],
      "Taste aversion can form from a single pairing even when illness comes hours later, which most classical conditioning does not allow. It shows biological preparedness to link taste with illness."),
    Q(0, 2, "Operant conditioning",
      "A cake is ready only after 30 minutes, so Leo rarely checks the oven at first and checks more often as 30 minutes approach. This pattern fits a",
      ["fixed-interval schedule", "fixed-ratio schedule", "variable-ratio schedule", "variable-interval schedule"],
      "On a fixed-interval schedule, reinforcement follows the first response after a set time, producing a scalloped pattern: little responding early and more as the time nears."),
    Q(0, 1, "Operant conditioning",
      "A teacher assigns extra homework when a student talks during a test, and the talking stops. This is",
      ["positive punishment", "negative punishment", "negative reinforcement", "positive reinforcement"],
      "Adding something unpleasant (extra homework) to weaken a behavior is positive punishment. Negative punishment removes something pleasant, such as a privilege."),
    Q(0, 1, "Social and cognitive factors in learning",
      "Kohler's chimpanzee suddenly stacked boxes to reach bananas after a period with no progress. This is",
      ["insight learning", "trial-and-error learning", "latent learning", "shaping"],
      "Insight learning is a sudden realization of a solution. Trial-and-error learning is gradual, through repeated attempts."),
    Q(0, 2, "Operant conditioning",
      "Dogs that could not escape shocks in one setting later failed to escape even when escape was easy. This illustrates",
      ["learned helplessness", "spontaneous recovery", "instinctive drift", "extinction"],
      "Learned helplessness is passive resignation after repeated uncontrollable bad events. Instinctive drift is an animal reverting to instinctive behavior during training."),
]
